// Place searches (Brave place_search). LIMIT = 0 runs all jobs; set e.g. 4 for a cheap test run.
// exclude is tested on name, categories and address. 'theaterstra' drops the old ABH address (office moved to Lingnerallee 3 in May 2026).
const LIMIT = 0;
const DOC = 'doctor|physician|medical|clinic|practice|health|general_practitioner|pediatric|gyn|dentist|dental';
const jobs = [
  { query: 'Ausländerbehörde Dresden', category: 'auslaenderbehoerde', subcategory: 'auslaenderbehoerde', name_match: 'ausländerbehörde|auslaenderbehoerde|ausländerangelegenheiten|foreigners', exclude: 'e\.v\.|verein|theaterstra', max: 3 },
  { query: 'englischsprachiger Hausarzt Dresden', category: 'doctor', subcategory: 'hausarzt', cat_match: DOC, exclude: 'apotheke|pharmacy', max: 8 },
  { query: 'Apotheke Dresden Neustadt', category: 'pharmacy', subcategory: 'apotheke', cat_match: 'pharmacy|drugstore|chemist', name_match: 'apotheke|pharmacy', max: 8 },
  { query: 'Ostsächsische Sparkasse Dresden Filiale', category: 'bank', subcategory: 'sparkasse', name_match: 'sparkasse', max: 6 },
  { query: 'Hausarzt Dresden English speaking', category: 'doctor', subcategory: 'hausarzt', cat_match: DOC, exclude: 'apotheke|pharmacy', max: 8 },
  { query: 'Kinderarzt Dresden', category: 'doctor', subcategory: 'kinderarzt', cat_match: DOC, exclude: 'apotheke|pharmacy', max: 8 },
  { query: 'Frauenarzt Dresden englisch', category: 'doctor', subcategory: 'frauenarzt', cat_match: DOC, exclude: 'apotheke|pharmacy', max: 8 },
  { query: 'Zahnarzt Dresden English', category: 'doctor', subcategory: 'zahnarzt', cat_match: DOC, exclude: 'apotheke|pharmacy', max: 8 },
  { query: 'Apotheke Dresden Altstadt', category: 'pharmacy', subcategory: 'apotheke', cat_match: 'pharmacy|drugstore|chemist', name_match: 'apotheke|pharmacy', max: 8 },
  { query: 'Deutsche Bank Dresden', category: 'bank', subcategory: 'deutsche_bank', name_match: 'deutsche bank', max: 4 },
  { query: 'Commerzbank Dresden', category: 'bank', subcategory: 'commerzbank', name_match: 'commerzbank', max: 4 },
  { query: 'Welcome Center Dresden', category: 'community', subcategory: 'welcome_center', name_match: 'welcome|willkommen|international', max: 4 },
  { query: 'Migrationsberatung Dresden', category: 'community', subcategory: 'migrant_counselling', name_match: 'migration|beratung|caritas|diakonie|awo|ausländerrat|auslaenderrat|integration', max: 6 },
  { query: 'Sprachcafé Dresden', category: 'community', subcategory: 'language_cafe', name_match: 'sprach|language|tandem|begegnung|international', max: 5 },
  { query: 'TU Dresden International Office', category: 'community', subcategory: 'international_office', name_match: 'international|tu dresden|technische universität|studentenwerk', max: 3 },
  { query: 'International Community Dresden Treffpunkt', category: 'community', subcategory: 'international_community', name_match: 'international|expat|community|begegnung|verein', max: 5 }
];
const list = LIMIT > 0 ? jobs.slice(0, LIMIT) : jobs;
return list.map(j => ({ json: j }));

// Turn Brave place results into rows for public.resources (uniform keys for PostgREST bulk upsert).
const jobs = $('Place Jobs').all().map(i => i.json);
const now = new Date().toISOString();
const rows = [];
const seen = new Set();
const failed = [];
const perJob = [];
const fmtDays = d => (Array.isArray(d) ? d : []).map(day => (Array.isArray(day) ? day : [day])
  .filter(Boolean).map(s => (s.abbr_name || '') + ' ' + (s.opens || '?') + '-' + (s.closes || '?')).join(', ')).filter(Boolean).join('; ');
$input.all().forEach((item, i) => {
  const pi = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : i;
  const job = jobs[pi] || jobs[i] || {};
  const res = item.json || {};
  if (res.error || !Array.isArray(res.results)) {
    failed.push({ query: job.query, error: String((res.error && (res.error.message || res.error)) || 'no results array').slice(0, 200) });
    return;
  }
  const nameRe = job.name_match ? new RegExp(job.name_match, 'i') : null;
  const catRe = job.cat_match ? new RegExp(job.cat_match, 'i') : null;
  const exRe = job.exclude ? new RegExp(job.exclude, 'i') : null;
  let kept = 0;
  for (const r of res.results) {
    if (kept >= (job.max || 8)) break;
    const name = (r.title || '').trim();
    const address = ((r.postal_address && r.postal_address.displayAddress) || '').trim();
    if (!name) continue;
    const pc = address.match(/\b(01[0-3]\d\d)\b/);
    if (!pc) continue; // only Dresden postcodes (010xx-013xx)
    const cats = ((r.categories || []).join(' ') + ' ' + (r.icon_category || '')).trim();
    if (nameRe && !nameRe.test(name)) continue;
    if (catRe && cats && !catRe.test(cats)) continue;
    if (exRe && (exRe.test(name) || exRe.test(cats) || exRe.test(address))) continue;
    const key = job.category + '|' + name.toLowerCase() + '|' + address.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    kept++;
    const after = address.split(pc[1])[1];
    const districtRaw = after ? after.replace(/^[\s,]+/, '').replace(/,\s*Germany$/i, '').replace(/^Dresden-/i, '').trim() : '';
    const district = districtRaw && districtRaw.toLowerCase() !== 'dresden' ? districtRaw : null;
    const coords = Array.isArray(r.coordinates) ? r.coordinates : [];
    const hours = r.opening_hours ? fmtDays(r.opening_hours.days) : '';
    rows.push({
      category: job.category,
      subcategory: job.subcategory || null,
      name,
      address: address || null,
      district,
      city: 'Dresden',
      lat: typeof coords[0] === 'number' ? coords[0] : null,
      lng: typeof coords[1] === 'number' ? coords[1] : null,
      phone: (r.contact && r.contact.telephone) || null,
      website: r.url || null,
      languages: null,
      opening_hours: hours || null,
      notes_en: 'Found via Brave place search "' + job.query + '" on ' + now.slice(0, 10) + '. Public business listing only. Languages spoken, opening hours and phone are NOT verified and may change: check with the place before you go.',
      source: 'brave',
      source_url: r.url || ('https://search.brave.com/search?q=' + encodeURIComponent(name + ' ' + address)),
      retrieved_at: now
    });
  }
  perJob.push({ query: job.query, kept, found: res.results.length });
});
const byCategory = {};
rows.forEach(r => { byCategory[r.category] = (byCategory[r.category] || 0) + 1; });
return [{ json: { rows, stats: { rows: rows.length, byCategory, perJob, failed } } }];

// Guide topics: Brave web search (trusted sources only) -> Firecrawl scrape top URLs -> Claude.
// LIMIT = 0 runs all guides; set 1 for a cheap test run. MAX_URLS = pages scraped per guide.
const LIMIT = 0;
const MAX_URLS = 2;
const guides = [
  { slug: 'auslaenderbehoerde-dresden-appointment', topic: 'auslaenderbehoerde', title_hint: 'Foreigners office (Ausländerbehörde) Dresden: appointment and documents',
    query: 'Ausländerbehörde Dresden Termin Unterlagen site:dresden.de', allow: ['dresden.de'] },
  { slug: 'bank-account-documents', topic: 'bank', title_hint: 'Opening a bank account in Germany: documents and the right to a Basiskonto',
    query: 'Basiskonto Anspruch Girokonto eröffnen Unterlagen Verbraucherzentrale', allow: ['verbraucherzentrale.de', 'bafin.de', 'make-it-in-germany.com', 'bundesbank.de', 'sparkasse.de', 'ostsaechsische-sparkasse.de'] },
  { slug: 'anmeldung-dresden', topic: 'anmeldung', title_hint: 'Registering your address (Anmeldung) at the Bürgerbüro Dresden',
    query: 'Wohnsitz anmelden Dresden Bürgerbüro Unterlagen site:dresden.de', allow: ['dresden.de'] },
  { slug: 'health-insurance-registration', topic: 'health_insurance', title_hint: 'Getting health insurance in Germany as a newcomer',
    query: 'health insurance Germany newcomers statutory register make-it-in-germany', allow: ['make-it-in-germany.com', 'bundesgesundheitsministerium.de', 'verbraucherzentrale.de'] }
];
const list = LIMIT > 0 ? guides.slice(0, LIMIT) : guides;
return list.map(g => ({ json: Object.assign({ max_urls: MAX_URLS }, g) }));

// Keep only allow-listed domains; never Arztsuche/Doctolib/Jameda/Google Maps. One item per URL to scrape.
const DENY = /116117|kvsachsen|kvs-sachsen|arztsuche|doctolib|jameda|google\.[a-z.]+\/maps|maps\.google/i;
const guides = $('Guide Jobs').all().map(i => i.json);
const out = [];
$input.all().forEach((item, i) => {
  const pi = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : i;
  const g = guides[pi] || guides[i];
  if (!g) return;
  const results = (item.json && item.json.web && item.json.web.results) || [];
  const picked = [];
  for (const r of results) {
    if (picked.length >= (g.max_urls || 2)) break;
    const m = String(r.url || '').match(/^https?:\/\/([^\/?#:]+)/i);
    if (!m) continue;
    const host = m[1].toLowerCase();
    if (DENY.test(r.url)) continue;
    if (!g.allow.some(d => host === d || host.endsWith('.' + d))) continue;
    if (/\.pdf($|\?)/i.test(r.url)) continue;
    if (picked.some(p => p.url === r.url)) continue;
    picked.push({ url: r.url, title: (r.title || '').replace(/<[^>]+>/g, '') });
  }
  picked.forEach(p => out.push({ json: { slug: g.slug, topic: g.topic, title_hint: g.title_hint, url: p.url, title: p.title } }));
});
if (out.length === 0) out.push({ json: { skip: true, slug: '', url: '' } });
return out;

// Runs once per item: keep only what the guide step needs.
const src = $('Loop Over URLs').first().json;
const r = $json || {};
const md = (r.data && r.data.markdown) || '';
const meta = (r.data && r.data.metadata) || {};
const status = meta.statusCode || (r.success ? 200 : 0);
const ok = !src.skip && !r.error && r.success !== false && status > 0 && status < 400 && md.length > 200;
return { json: {
  slug: src.slug, topic: src.topic, title_hint: src.title_hint,
  url: meta.url || meta.sourceURL || src.url,
  title: meta.title || src.title || '',
  ok, status,
  error: ok ? null : String((r.error && (r.error.message || r.error)) || meta.error || 'empty or failed page').slice(0, 200),
  markdown: ok ? md.slice(0, 12000) : '',
  retrieved_at: new Date().toISOString()
} };

// One item per guide with combined source text; guides without usable text are reported, not sent to Claude.
const bySlug = {};
const failedPages = [];
for (const it of $input.all()) {
  const p = it.json;
  if (!p.slug) continue;
  if (!p.ok) { failedPages.push({ slug: p.slug, url: p.url, status: p.status, error: p.error }); continue; }
  bySlug[p.slug] = bySlug[p.slug] || { slug: p.slug, topic: p.topic, title_hint: p.title_hint, sources: [], parts: [] };
  if (bySlug[p.slug].sources.some(s => s.url === p.url)) continue;
  bySlug[p.slug].sources.push({ url: p.url, title: p.title, retrieved_at: p.retrieved_at });
  bySlug[p.slug].parts.push('### SOURCE ' + bySlug[p.slug].sources.length + ': ' + p.title + ' (' + p.url + ')\n' + p.markdown);
}
const guides = Object.values(bySlug).map(g => ({ json: {
  has_text: true, slug: g.slug, topic: g.topic, title_hint: g.title_hint, sources: g.sources,
  source_text: g.parts.join('\n\n'), failed_pages: failedPages
} }));
if (guides.length === 0) return [{ json: { has_text: false, failed_pages: failedPages } }];
return guides;

