// Parse Claude's strict JSON and build rows for public.guides (uniform keys).
const inputs = $('Group by Guide').all().map(i => i.json).filter(g => g.has_text);
const now = new Date().toISOString();
const rows = [];
const failed = [];
$input.all().forEach((item, i) => {
  const pi = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : i;
  const g = inputs[pi] || inputs[i];
  if (!g) return;
  const r = item.json || {};
  if (r.error) { failed.push({ slug: g.slug, error: String(r.error.message || r.error).slice(0, 200) }); return; }
  const text = (Array.isArray(r.content) ? r.content : []).filter(c => c.type === 'text').map(c => c.text).join('\n').trim();
  let obj = null;
  try {
    const s = text.indexOf('{');
    const e = text.lastIndexOf('}');
    obj = JSON.parse(text.slice(s, e + 1));
  } catch (err) { failed.push({ slug: g.slug, error: 'invalid JSON from model' }); return; }
  if (!obj || !obj.title_en || !obj.summary_en) { failed.push({ slug: g.slug, error: 'missing title_en/summary_en' }); return; }
  const checklist = (Array.isArray(obj.checklist) ? obj.checklist : []).map(x => String(x).trim()).filter(Boolean);
  const footer = '\n\n---\n*Generated from the official sources below on ' + now.slice(0, 10) + '. Rules, fees and opening hours can change. Always check the source before you go.*\n\n' +
    g.sources.map(s => '- [' + (s.title || s.url) + '](' + s.url + ')').join('\n');
  rows.push({
    slug: g.slug, topic: g.topic, city: 'Dresden',
    title_en: String(obj.title_en).trim(), summary_en: String(obj.summary_en).trim(),
    checklist, content_md: String(obj.content_md || '').trim() + footer,
    sources: g.sources, updated_at: now
  });
});
return [{ json: { rows, stats: { guides: rows.length, slugs: rows.map(r => r.slug), failed, failed_pages: (inputs[0] && inputs[0].failed_pages) || [] } } }];

// Collect counts for the events log. Works whether or not the guide branch produced rows.
const safe = f => { try { return f(); } catch (e) { return null; } };
const places = safe(() => $('Map Places to Rows').first().json.stats) || {};
const resStatus = safe(() => $('Upsert Resources').first().json.statusCode);
const guides = safe(() => $('Build Guide Rows').first().json.stats) || { guides: 0, slugs: [], failed: [] };
const guideStatus = safe(() => $('Upsert Guides').first().json.statusCode);
const grouped = safe(() => $('Group by Guide').first().json) || {};
return [{ json: { payload: {
  workflow: $workflow.name, execution: $execution.id,
  resources_rows: places.rows || 0, resources_by_category: places.byCategory || {},
  resources_upsert_status: resStatus, place_jobs: places.perJob || [], place_jobs_failed: places.failed || [],
  guides_rows: guides.guides || 0, guides_slugs: guides.slugs || [], guides_upsert_status: guideStatus,
  guides_failed: guides.failed || [], guide_pages_failed: guides.failed_pages || grouped.failed_pages || []
} } }];
